"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"step must divide an hour evenly: {step}")


def _snap(minute: int, step: int) -> int:
    return (minute + step // 2) // step * step


def _clock(minute: int) -> str:
    return "%02d:%02d" % divmod(minute, 60)


# ---
def round_span_labels(spans: Iterable[Span], step: int) -> List[str]:
    """Round each start and end to the nearest step, halves going up."""
    _check_step(step)
    labels = []
    for span in spans:
        rounded = Span(_snap(span.start, step), _snap(span.end, step))
        hours, mins = divmod(rounded.minutes, 60)
        clock = f"{_clock(rounded.start)}-{_clock(rounded.end)}"
        labels.append(f"{clock} ({hours}h {mins}m)")
    return labels

